!function(e){function a(a){for(var r,p,n=a[0],m=a[1],o=a[2],g=0,_=[];g<n.length;g++)p=n[g],Object.prototype.hasOwnProperty.call(t,p)&&t[p]&&_.push(t[p][0]),t[p]=0;for(r in m)Object.prototype.hasOwnProperty.call(m,r)&&(e[r]=m[r]);for(c&&c(a);_.length;)_.shift()();return d.push.apply(d,o||[]),i()}function i(){for(var e,a=0;a<d.length;a++){for(var i,p=d[a],n=!0,m=1;m<p.length;m++)i=p[m],0!==t[i]&&(n=!1);n&&(d.splice(a--,1),e=r(r.s=p[0]))}return e}function r(a){if(p[a])return p[a].exports;var i=p[a]={i:a,l:!1,exports:{}};return e[a].call(i.exports,i,i.exports,r),i.l=!0,i.exports}var p={},t={96:0},d=[];r.m=e,r.c=p,r.d=function(e,a,i){r.o(e,a)||Object.defineProperty(e,a,{enumerable:!0,get:i})},r.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},r.t=function(e,a){if(1&a&&(e=r(e)),8&a)return e;if(4&a&&"object"==typeof e&&e&&e.__esModule)return e;var i=Object.create(null);if(r.r(i),Object.defineProperty(i,"default",{enumerable:!0,value:e}),2&a&&"string"!=typeof e)for(var p in e)r.d(i,p,function(a){return e[a]}.bind(null,p));return i},r.n=function(e){var a=e&&e.__esModule?function(){return e.default}:function(){return e};return r.d(a,"a",a),a},r.o=function(e,a){return Object.prototype.hasOwnProperty.call(e,a)},r.p="";var n=window.webpackJsonp=window.webpackJsonp||[],m=n.push.bind(n);n.push=a,n=n.slice();for(var o=0;o<n.length;o++)a(n[o]);var c=m;d.push([136,0]),i()}({136:function(e,a,i){"use strict";i.r(a);var r=i(0);Object(r.a)("de","army",i(137),i(1))},137:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"轮式装甲车","link":"de_army#de_army_wav"}],"model":"Sdkfz 221/222型4轮装甲侦察车","description":"<p>Sdkfz 221型与Sdkfz 221型都是4轮装甲侦察车、 Sdkfz 221型4轮装甲侦察车在二战前（1935年左右）就开始研制，1936年德军对Sdkfz 221型进行了改进，在Sdkfz 221型车体上加装了一个装备20mm机关炮的炮塔，并加厚了正面装甲厚度，从而加强了火力与防护力，并定型为Sdkfz 222型。</p><p>Sdkfz 221型4轮装甲侦察车在1940年停产，一共生产了339辆。Sdkfz 222型4轮装甲侦察车从1936年开始改装至1943年停止生产，共生产了989辆。这两型侦察车都装备给德军的侦察部队，除作前方侦察外，Sdkfz 222型还经常为德军步兵提供火力支援，并与对手的轻型装甲车交火。这二型侦察车都携带一台小功率通讯电台，在战场上作为各战车的短程联络用。二战开始，这些4轮侦察车都随德军部队参加了战斗，特别是Sdkfz 222型4轮装甲侦察车更是在广泛地出现在二战早期的各个战场上。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_wav221&222_11.jpg","description":"<h6>Sdkfz 221型4轮装甲侦察车（早期型）</h6><p></p><p>技术数据：</p><p>车长：4.8米，车宽：1.95米，车高：1.7米；战斗全重：4.4吨；乘员2人。</p><p>发动机功率：75马力，最高车速：90公里/小时，最大行程：320千米。</p><p>装甲厚度：5～8mm。</p><p>武器配备：一挺MG34型7.92mm重机枪，备弹1050发。</p>","caption":""},{"image":"imgs/de/army/de_army_wav221&222_12.jpg","description":"<h6>Sdkfz 221型4轮装甲侦察车（后期型）</h6><p></p><p>后期生产的Sdkfz 221型4轮装甲侦察车将正面装甲厚度提升到30mm，武器也改为一门28mm sPzB 41型反坦克炮。该型车在二战初期大量投入到波兰、法国和苏联战场中,执行侦察与巡逻任务。</p>","caption":""},{"image":"imgs/de/army/de_army_wav221&222_13.jpg","description":"<h6>Sdkfz 222型4轮装甲侦察车</h6><p></p><p>技术数据</p><p>车长：4.8米，车宽：1.95米，车高：1.75米；战斗全重：4.8吨；乘员3人。</p><p>发动机功率：75马力，最高车速：85千米/小时，最大行程：300千米。</p><p>装甲厚度：14.0～30.0毫米。</p><p>武器配备：一门KwK30型20mm机关炮，一挺MG 34型7.92mm机枪。</p>","caption":""}],"part2title":"战场上的Sdkfz 221/222型4轮装甲侦察车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_wav221&222_21.jpg","description":"1940年5月，西线战场法国北部城市布伦，隶属德军第2装甲师第5侦察营的一辆Sdkfz 221型4轮装甲侦察车（早期型）。","caption":""},{"image":"imgs/de/army/de_army_wav221&222_22.jpg","description":"1942年夏天，东线苏联战场，隶属德国武装党卫军第5“维京”装甲师侦察营一辆编号为“SS-108644”的Sdkfz 221型4轮装甲侦察车（早期型）。","caption":""},{"image":"imgs/de/army/de_army_wav221&222_23.jpg","description":"1942年夏天，东线苏联战场，隶属德国武装党卫军第2“帝国”装甲师侦察营一辆编号为“SS-5944”的Sdkfz 221型4轮装甲侦察车（早期型）。","caption":""},{"image":"imgs/de/army/de_army_wav221&222_24.jpg","description":"1941年5月，巴尔干半岛希腊地区，隶属德军第5装甲师侦察营的一辆Sdkfz 222型4轮装甲侦察车。","caption":""},{"image":"imgs/de/army/de_army_wav221&222_25.jpg","description":"1939年3月，立陶宛梅黙尔（克莱佩特的旧称）地区，德军（单位不明）一辆Sdkfz 222型4轮装甲侦察车。","caption":""},{"image":"imgs/de/army/de_army_wav221&222_26.jpg","description":"1943年4月，非洲战场突尼斯地区，隶属德军第164轻装师的一辆Sdkfz 222型4轮装甲侦察车。","caption":""},{"image":"imgs/de/army/de_army_wav221&222_27.jpg","description":"1939年9月，德国武装党卫军第1“阿道夫·希特勒警卫旗队”装甲师的一辆Sdkfz 221型4轮装甲侦察车正在执行护送希特勒奔驰车队的任务。","caption":""},{"image":"imgs/de/army/de_army_wav221&222_28.jpg","description":"1941年7月，东线苏联战场白俄罗斯地区，德国某装甲师第7装甲侦察营的一辆Sdkfz 221型4轮装甲侦察车正在战场上执行侦察任务。","caption":""},{"image":"imgs/de/army/de_army_wav221&222_29.jpg","description":"1942年北非战场，在沙漠行进的一支德军车队，车队中有Sdkfz 221型4轮装甲侦察车与Sdkfz 251半履带装甲车（图中央）。","caption":""},{"image":"imgs/de/army/de_army_wav221&222_30.jpg","description":"这是在作战状态中的一辆德军Sdkfz 221型4轮装甲侦察车，一德军士兵以该车作掩护进行射击。","caption":""},{"image":"imgs/de/army/de_army_wav221&222_31.jpg","description":"1943年，一辆德军Sdkfz 221型4轮装甲侦察车正在补充物资（油料），该车车身上方铺着一面万字旗以作防空识别，看来这辆4轮装甲车即将要开赴前线。","caption":""},{"image":"imgs/de/army/de_army_wav221&222_32.jpg","description":"1941年夏天，东线苏联战场，向前线开进的德军某装甲师侦察营的车队，前面第一辆的是Sdkfz 221型4轮装甲侦察车。","caption":""},{"image":"imgs/de/army/de_army_wav221&222_33.jpg","description":"1941年，东线苏联战场，德国武装党卫军第1“阿道夫·希特勒警卫旗队”装甲师一辆Sdkfz 222型4轮装甲侦察车正为进攻的德军作火力支援。","caption":""},{"image":"imgs/de/army/de_army_wav221&222_34.jpg","description":"1941年，东线苏联战场，德军第24装甲师一队行进的车队，在领头的一辆Sdkfz 222型4轮装甲侦察车后面是一辆Sdkfz 223型4轮装甲通讯车。","caption":""},{"image":"imgs/de/army/de_army_wav221&222_35.jpg","description":"1941年4月，行进在保加利亚地区的德国武装党卫军第1“阿道夫·希特勒警卫旗队”装甲师一辆编号为”SS-49736“的Sdkfz 222型4轮装甲侦察车。","caption":""},{"image":"imgs/de/army/de_army_wav221&222_36.jpg","description":"这是隶属德国武装党卫军第1“阿道夫·希特勒警卫旗队”装甲师侦察营一辆Sdkfz 222型4轮装甲侦察车。注意该车车头前有一块铆接的钢板，这是因为车体正面装甲太薄，为了加强防护而补上去的。","caption":""},{"image":"imgs/de/army/de_army_wav221&222_37.jpg","description":"1942年，北非战场，德军一队Sdkfz 222型4轮装甲侦察车正在前线执行侦察任务。","caption":""},{"image":"imgs/de/army/de_army_wav221&222_38.jpg","description":"北非战场，英军正在检查一辆缴获的德军Sdkfz 222型4轮装甲侦察车。","caption":""},{"image":"imgs/de/army/de_army_wav221&222_39.jpg","description":"手绘作品：东线苏联战场，一德军摩托通讯兵赶至Sdkfz 222型4轮装甲侦察车旁传达任务。","caption":""},{"image":"imgs/de/army/de_army_wav221&222_40.jpg","description":"手绘作品：东线苏联战场上的德军Sdkfz 222型4轮装甲侦察车，除了担负侦察任务外，还可在战场上与对手撕杀。","caption":""}]}')}});